local mixes = {
 {"soilA", {["indian-red"]=0.12, ["burnt-umber"]=0.15, ["french-ultramarine"]=0.03}},
 {"soilB", {["burnt-sienna"]=0.12, ["raw-umber"]=0.12, ["indian-red"]=0.06, ["french-ultramarine"]=0.02}},
