-- Campaign 1: sky. Pre-wet, graded blue wash, lift clouds while wet.
for gy=0,3 do for gx=0,9 do
  drop{x=250+gx*105 + (gy%2)*50, y=25+gy*95, water=6, radius=80}
end end
