e:load{water=6, pigments={["cobalt-blue"]=0.07, ["french-ultramarine"]=0.035, ["burnt-sienna"]=0.01}}
e:stroke({{1000,130},{1100,118},{1190,108}}, {pressure=0.4, duration=0.2})
