d:load{water=5, pigments={["cobalt-blue"]=0.06, ["french-ultramarine"]=0.03, ["burnt-sienna"]=0.008}}
for _,p in ipairs({{745,72},{800,100},{880,105},{930,140},{990,150},{760,65}}) do
  d:stroke({{p[1],p[2]},{p[1]+25,p[2]-3}}, {pressure=0.4})
end
