 {{222,262},{250,246},{285,244},{312,256}},
 {{215,278},{255,268},{300,270},{322,282}},
 {{225,292},{265,288},{305,292}},
}
for i,p in ipairs(paths) do top(R, gm, 2.2, 0.8 + i*0.25); R:stroke(p, {pressure=0.5, duration=0.08}) end
