local dm = {["sepia"]=0.08, ["french-ultramarine"]=0.05, ["paynes-gray"]=0.03}
top(D, dm, 1.2)
D:stroke({{218,298},{250,302},{290,304},{320,296}}, {pressure=0.5, duration=0.08})
